+#[test]
+fn a_by_part_stop_is_written_once_after_the_last_copy() {
+    let (world, mut h) = three_faces();
+    h.execute(&world, EditOperationParams::with_after(&world, "Face2", AfterOperation::ProgramStop).expect("stop after Face2"));
