+    c.ok(
+        "add_operation",
+        json!({
+            "kind": "pocket", "tool": "EM-0400-2FL", "name": "P1", "source": "plate",
+            "params": {
+                "top_z": { "reference": "fixed", "offset": face_z + 1.0 },
