+    let shown = &g["source"]["picks"][0];
+    assert_eq!(shown["id"], up["id"], "{g}");
+    for key in ["source_name", "source_names", "source_unverified"] {
+        assert_eq!(shown.get(key), up.get(key), "{key}: {g}");
+    }
+}

