+}
+
+#[test]
+fn klartext_invalid_cycle_definitions_and_calls_are_refused() {
+    let cases = [
+        "CYCL DEF 200 DRILLING Q200=2 Q206=100 Q202=5 Q203=0 Q204=0",
+        "CYCL DEF 200 DRILLING Q200=2 Q201=+5 Q206=100 Q202=5 Q203=0 Q204=0",
