+            short(er.min_bore, u),
+            short(er.max_bore, u),
+            u.suffix(),
+            er.name
+        ),
+        Clamp::Weldon { bore, .. } | Clamp::Shrink { bore, .. } => {
+            format!("{FITS} the shank Ø{s} takes the Ø{} {} bore of the holder.", short(bore, u), u.suffix())
+        }
+    })
